mapper.select:
SELECT c.id FROM afv_resource_command c WHERE c.committed_at IS NOT NULL AND


        EXISTS (SELECT 1 FROM afv_resource_event e WHERE e.command_id = c.id AND e.project_id = #{projectId})


        (c.canvas_id = #{canvasId} OR EXISTS (
            SELECT 1 FROM afv_resource_event e JOIN afv_canvas_node n ON n.resource_type = e.resource_type
            AND n.resource_id = e.resource_id AND n.deleted = FALSE WHERE e.command_id = c.id AND n.canvas_id = #{canvasId}
        ))



    AND (c.committed_at < #{beforeTime} OR (c.committed_at = #{beforeTime} AND c.id < #{beforeId}))

ORDER BY c.committed_at DESC, c.id DESC LIMIT #{limit}
